import json
import math
import subprocess
import time
from pathlib import Path
from urllib.error import URLError
from urllib.parse import urlencode
from urllib.request import urlopen

backend = "http://127.0.0.1:8080"
prometheus = "http://127.0.0.1:9091"

def get(url):
    with urlopen(url, timeout=3) as response:
        return response.read().decode()

def call_grpc(size):
    return subprocess.run([
        "grpcurl", "-plaintext", "-max-time", "5", "-import-path", "src/backend/src/main/proto",
        "-proto", "frameinventory/v1/frames.proto", "-d", json.dumps({"size": size}),
        "127.0.0.1:9090", "frameinventory.v1.FrameManagement/ListFrames",
    ], capture_output=True, text=True)

for attempt in range(40):
    try:
        get(backend + "/api/health")
        call_grpc(1)
        metrics = get(backend + "/actuator/prometheus")
        if "http_server_requests_seconds_bucket" in metrics and "grpc_server_seconds_bucket" in metrics:
            break
    except URLError:
        pass
    time.sleep(3)
else:
    raise SystemExit("HTTP and gRPC histogram buckets did not appear")
print("Verified HTTP and gRPC histogram buckets", flush=True)

dashboard = json.loads(Path("monitoring/dashboards/frame-inventory-backend.json").read_text())
targets = [target for panel in dashboard["panels"] for target in panel.get("targets", [])]
for attempt in range(15):
    get(backend + "/api/health")
    successful = call_grpc(1)
    assert successful.returncode == 0, successful.stderr
    rejected = call_grpc(51)
    assert rejected.returncode != 0 and "InvalidArgument" in rejected.stderr, rejected.stderr
    results = {}
    try:
        for target in targets:
            query = target["expr"].replace("$__rate_interval", "1m")
            response = json.loads(get(prometheus + "/api/v1/query?" + urlencode({"query": query})))
            results[target["legendFormat"]] = [float(sample["value"][1]) for sample in response["data"]["result"]]
    except URLError:
        time.sleep(4)
        continue
    all_finite = all(values and all(math.isfinite(value) for value in values) for values in results.values())
    if all_finite and results["gRPC non-OK"][0] > 0:
        for label, values in results.items():
            print(label, values)
        break
    time.sleep(4)
else:
    raise SystemExit(f"Some dashboard queries did not return expected data: {results}")
