def grpc(size):
    return subprocess.run([
        "grpcurl", "-plaintext", "-max-time", "5", "-import-path", "src/backend/src/main/proto",
        "-proto", "frameinventory/v1/frames.proto", "-d", json.dumps({"size": size}),
        "127.0.0.1:9090", "frameinventory.v1.FrameManagement/ListFrames",
    ], capture_output=True, text=True)

def drive_traffic():
    read("http://127.0.0.1:8080/api/health")
    ok = grpc(1)
    assert ok.returncode == 0, ok.stderr
    rejected = grpc(51)
    assert rejected.returncode != 0 and "InvalidArgument" in rejected.stderr, rejected.stderr

drive_traffic()
metrics = read("http://127.0.0.1:8080/actuator/prometheus")
for prefix in ("http_server_requests", "grpc_server"):
    assert prefix + "_seconds_bucket{" in metrics, prefix
print("Verified HTTP and gRPC histogram buckets", flush=True)

dashboard = json.loads(Path("monitoring/dashboards/frame-inventory-backend.json").read_text())
targets = [target for panel in dashboard["panels"] for target in panel.get("targets", [])]
for attempt in range(15):
    drive_traffic()
    results = {}
    for target in targets:
        query = target["expr"].replace("$__rate_interval", "1m")
        response = json.loads(read("http://127.0.0.1:9091/api/v1/query?" + urlencode({"query": query})))
        results[target["legendFormat"]] = [float(sample["value"][1]) for sample in response["data"]["result"]]
    if all(values and all(math.isfinite(value) for value in values) for values in results.values()) and results["gRPC non-OK"][0] > 0:
        for label, values in results.items():
            print(label, values)
        break
    time.sleep(4)
else:
    raise SystemExit(f"Some dashboard queries did not return expected data: {results}")
PY`;
